<script setup>
import { computed } from 'vue'
const props = defineProps({ open: Boolean, items: { type: Array, default: () => [] } })
const emit = defineEmits(['close', 'update', 'remove', 'shop'])
const total = computed(() => props.items.reduce((sum, item) => sum + item.price * item.quantity, 0))
const imageUrl = image => `https://images.unsplash.com/${image}?auto=format&fit=crop&w=200&q=75`
function showDemoNotice() { window.alert('这是前端交互练习 Demo，不提供真实下单或支付。') }
</script>
<template><Transition name="drawer"><div v-if="open" class="drawer-backdrop" @click.self="emit('close')"><aside class="cart-drawer"><div class="drawer-heading"><div><p class="eyebrow">YOUR LITTLE TREASURES</p><h2>购物袋 <span>({{ items.reduce((n, item) => n + item.quantity, 0) }})</span></h2></div><button class="drawer-close" aria-label="关闭购物袋" @click="emit('close')">×</button></div><div v-if="!items.length" class="cart-empty"><div>♧</div><h3>购物袋还空空的</h3><p>去挑一件喜欢的好物吧。</p><button class="button button-dark" @click="emit('shop'); emit('close')">去逛逛 <span>↗</span></button></div><div v-else class="cart-content"><div class="cart-items"><article v-for="item in items" :key="item.id" class="cart-item"><img :src="imageUrl(item.image)" :alt="item.name"/><div class="cart-item-info"><div class="cart-item-title"><h3>{{ item.name }}</h3><button aria-label="删除商品" @click="emit('remove', item.id)">×</button></div><p>{{ item.color }} · ¥{{ item.price }}</p><div class="quantity-control"><button :aria-label="`减少${item.name}数量`" @click="emit('update', item.id, -1)">−</button><span>{{ item.quantity }}</span><button :aria-label="`增加${item.name}数量`" @click="emit('update', item.id, 1)">＋</button></div></div><b class="cart-item-total">¥{{ item.price * item.quantity }}</b></article></div><div class="cart-summary"><p><span>商品小计</span><b>¥{{ total }}</b></p><p><span>配送</span><span>满 ¥199 包邮</span></p><div class="summary-total"><span>合计</span><b>¥{{ total }}</b></div><button class="button button-dark checkout-button" @click="showDemoNotice">仅供展示 · 暂不支持结算 <span>↗</span></button><small>前端练习 Demo · 没有真实支付或下单</small></div></div></aside></div></Transition></template>
